import Foundation

enum ClipboardPrivacy {
    static let skipTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType"
    ]

    static let passwordAppBundleIdentifiers: Set<String> = [
        "com.apple.Passwords",
        "com.apple.keychainaccess"
    ]

    static func shouldSkip(types: Set<String>, frontmostBundleIdentifier: String?) -> Bool {
        if !types.isDisjoint(with: skipTypes) {
            return true
        }
        guard let frontmostBundleIdentifier else { return false }
        return passwordAppBundleIdentifiers.contains(frontmostBundleIdentifier)
    }
}

struct ClipboardEntry: Codable, Equatable, Identifiable {
    let id: UUID
    var text: String
    var isPinned: Bool
    var createdAt: Date
    /// The bundle identifier of the app that was in front when this was copied. Items saved by
    /// older versions have none. Only the identifier is stored; the icon is looked up when drawn.
    var sourceApp: String?

    init(id: UUID = UUID(), text: String, isPinned: Bool = false, createdAt: Date = Date(), sourceApp: String? = nil) {
        self.id = id
        self.text = text
        self.isPinned = isPinned
        self.createdAt = createdAt
        self.sourceApp = sourceApp
    }

    /// A single web address, so the shelf can show a link icon instead of a text one.
    var looksLikeLink: Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, !trimmed.contains(where: { $0.isWhitespace }) else { return false }
        guard let url = URL(string: trimmed), let scheme = url.scheme?.lowercased() else { return false }
        return (scheme == "http" || scheme == "https") && url.host != nil
    }
}

struct ClipboardHistory: Equatable {
    /// How many recent (unpinned) items the shelf can keep; pinned items never count.
    static let recentLimitOptions = [20, 50, 100]
    static let defaultRecentLimit = 20

    /// A stored limit if it's one of the offered choices, otherwise the default.
    static func validRecentLimit(_ stored: Int) -> Int {
        recentLimitOptions.contains(stored) ? stored : defaultRecentLimit
    }

    private(set) var entries: [ClipboardEntry]
    private(set) var maxRecentItems: Int

    init(entries: [ClipboardEntry] = [], maxRecentItems: Int = 20) {
        self.maxRecentItems = max(1, maxRecentItems)
        self.entries = entries
        normalize()
    }

    /// Adds a copy to the top. A repeated text moves up and takes the new source app; copying it
    /// again from the shelf itself (no source) keeps the app it first came from.
    mutating func record(_ text: String, at date: Date = Date(), sourceApp: String? = nil) {
        guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }

        if let index = entries.firstIndex(where: { $0.text == text }) {
            var existing = entries.remove(at: index)
            existing.createdAt = date
            if let sourceApp {
                existing.sourceApp = sourceApp
            }
            entries.append(existing)
        } else {
            entries.append(ClipboardEntry(text: text, createdAt: date, sourceApp: sourceApp))
        }
        normalize()
    }

    /// Changes how many recent items are kept. A smaller limit removes the oldest recent items.
    mutating func setMaxRecentItems(_ limit: Int) {
        maxRecentItems = max(1, limit)
        normalize()
    }

    var pinnedEntries: [ClipboardEntry] { entries.filter(\.isPinned) }
    var recentEntries: [ClipboardEntry] { entries.filter { !$0.isPinned } }

    mutating func togglePin(id: UUID) {
        guard let index = entries.firstIndex(where: { $0.id == id }) else { return }
        entries[index].isPinned.toggle()
        normalize()
    }

    mutating func remove(id: UUID) {
        entries.removeAll { $0.id == id }
    }

    mutating func clearRecent() {
        entries.removeAll { !$0.isPinned }
        normalize()
    }

    func filteredEntries(matching query: String) -> [ClipboardEntry] {
        let trimmed = query.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return entries }
        return entries.filter { $0.text.localizedCaseInsensitiveContains(trimmed) }
    }

    func encoded() throws -> Data {
        try JSONEncoder().encode(entries)
    }

    static func decode(data: Data, maxRecentItems: Int = 20) throws -> ClipboardHistory {
        let decoded = try JSONDecoder().decode([ClipboardEntry].self, from: data)
        return ClipboardHistory(entries: decoded, maxRecentItems: maxRecentItems)
    }

    private mutating func normalize() {
        var seenTexts = Set<String>()
        entries = entries.enumerated()
            .sorted { lhs, rhs in
                if lhs.element.isPinned != rhs.element.isPinned {
                    return lhs.element.isPinned && !rhs.element.isPinned
                }
                if lhs.element.createdAt != rhs.element.createdAt {
                    return lhs.element.createdAt > rhs.element.createdAt
                }
                return lhs.offset > rhs.offset
            }
            .map(\.element)
            .filter { seenTexts.insert($0.text).inserted }

        let pinned = entries.filter(\.isPinned)
        let recent = entries.filter { !$0.isPinned }.prefix(maxRecentItems)
        entries = pinned + recent
    }
}

/// The short times under each item: "Copied 8 minutes ago", "Pinned · Yesterday". With a source
/// app name: "Safari · Copied 8 minutes ago", "Pinned · Mail · Yesterday".
enum ClipboardTimeText {
    static func copied(_ date: Date, now: Date, calendar: Calendar = .current, locale: Locale = .current, app: String? = nil) -> String {
        let text = copiedText(date, now: now, calendar: calendar, locale: locale)
        guard let app else { return text }
        return "\(app) · \(text)"
    }

    static func pinned(_ date: Date, now: Date, calendar: Calendar = .current, locale: Locale = .current, app: String? = nil) -> String {
        let day = pinnedDay(date, now: now, calendar: calendar, locale: locale)
        guard let app else { return "Pinned · \(day)" }
        return "Pinned · \(app) · \(day)"
    }

    private static func copiedText(_ date: Date, now: Date, calendar: Calendar, locale: Locale) -> String {
        let seconds = now.timeIntervalSince(date)
        if seconds < 60 { return "Copied just now" }
        let minutes = Int(seconds / 60)
        if minutes < 60 { return minutes == 1 ? "Copied 1 minute ago" : "Copied \(minutes) minutes ago" }
        if calendar.isDate(date, inSameDayAs: now) {
            let hours = minutes / 60
            return hours == 1 ? "Copied 1 hour ago" : "Copied \(hours) hours ago"
        }
        if isYesterday(date, now: now, calendar: calendar) { return "Copied yesterday" }
        return "Copied \(shortDate(date, calendar: calendar, locale: locale))"
    }

    private static func pinnedDay(_ date: Date, now: Date, calendar: Calendar, locale: Locale) -> String {
        if calendar.isDate(date, inSameDayAs: now) || date > now { return "Today" }
        if isYesterday(date, now: now, calendar: calendar) { return "Yesterday" }
        return shortDate(date, calendar: calendar, locale: locale)
    }

    private static func isYesterday(_ date: Date, now: Date, calendar: Calendar) -> Bool {
        guard let yesterday = calendar.date(byAdding: .day, value: -1, to: now) else { return false }
        return calendar.isDate(date, inSameDayAs: yesterday)
    }

    private static func shortDate(_ date: Date, calendar: Calendar, locale: Locale) -> String {
        let formatter = DateFormatter()
        formatter.calendar = calendar
        formatter.timeZone = calendar.timeZone
        formatter.locale = locale
        formatter.setLocalizedDateFormatFromTemplate("MMMd")
        return formatter.string(from: date)
    }
}

/// The counts in the shelf's footer, like "4 recent · 2 pinned".
enum ClipboardSummaryText {
    static func counts(recent: Int, pinned: Int) -> String {
        pinned > 0 ? "\(recent) recent · \(pinned) pinned" : "\(recent) recent"
    }
}

/// When Clipboard Shelf may relaunch to install an update that has already downloaded.
enum UpdateInstallPolicy {
    /// How often the waiting installer asks again while the shelf is open.
    static let retryInterval: TimeInterval = 15

    /// The shelf is open, so the user may be using it. The update waits until it closes; quitting
    /// Clipboard Shelf still installs the update straight away.
    static func canInstallNow(isBusy: Bool) -> Bool {
        !isBusy
    }
}

/// A colour as plain numbers, so the skins can be listed and tested without any UI framework.
struct ShelfRGB: Equatable, Sendable {
    let red: Double
    let green: Double
    let blue: Double

    init(hex: UInt32) {
        red = Double((hex >> 16) & 0xFF) / 255
        green = Double((hex >> 8) & 0xFF) / 255
        blue = Double(hex & 0xFF) / 255
    }
}

/// The colour waves the shelf can wear. The accent drives the highlights, the pin colour the pinned
/// items, and the tint the dark background.
enum ShelfSkin: String, CaseIterable, Sendable {
    case lagoon
    case classic
    case grape
    case sunset
    case meadow
    case rose

    /// The skin a fresh install wears (Classic from 1.3.0; it was Lagoon before).
    static let fallback = ShelfSkin.classic
    /// The skin the app's own icon is drawn in, so it needs no custom icon in Finder.
    static let builtInIcon = ShelfSkin.lagoon

    /// A stored name if it is a known skin, otherwise Classic.
    static func from(stored: String?) -> ShelfSkin {
        guard let stored, let skin = ShelfSkin(rawValue: stored) else { return fallback }
        return skin
    }

    var title: String {
        switch self {
        case .lagoon: return "Lagoon"
        case .classic: return "Classic"
        case .grape: return "Grape"
        case .sunset: return "Sunset"
        case .meadow: return "Meadow"
        case .rose: return "Rose"
        }
    }

    var accent: ShelfRGB {
        switch self {
        case .lagoon: return ShelfRGB(hex: 0x14B8A6)
        case .classic: return ShelfRGB(hex: 0x0A84FF)
        case .grape: return ShelfRGB(hex: 0x8B5CF6)
        case .sunset: return ShelfRGB(hex: 0xFF6B4A)
        case .meadow: return ShelfRGB(hex: 0x30B85E)
        case .rose: return ShelfRGB(hex: 0xF0508C)
        }
    }

    var pin: ShelfRGB {
        switch self {
        case .lagoon, .meadow: return ShelfRGB(hex: 0xF5B134)
        case .classic: return ShelfRGB(hex: 0xFFB020)
        case .grape, .rose: return ShelfRGB(hex: 0xFFC247)
        case .sunset: return ShelfRGB(hex: 0xFFD166)
        }
    }

    var tint: ShelfRGB {
        switch self {
        case .lagoon: return ShelfRGB(hex: 0x14282C)
        case .classic: return ShelfRGB(hex: 0x1A2230)
        case .grape: return ShelfRGB(hex: 0x241C33)
        case .sunset: return ShelfRGB(hex: 0x2E1D22)
        case .meadow: return ShelfRGB(hex: 0x1A2A21)
        case .rose: return ShelfRGB(hex: 0x2E1C25)
        }
    }
}

/// Whether the shelf follows the Mac's light or dark look, or stays in one.
enum ShelfAppearance: String, CaseIterable, Sendable {
    case auto
    case light
    case dark

    static func from(stored: String?) -> ShelfAppearance {
        guard let stored, let value = ShelfAppearance(rawValue: stored) else { return .auto }
        return value
    }

    var title: String {
        switch self {
        case .auto: return "Automatic"
        case .light: return "Light"
        case .dark: return "Dark"
        }
    }
}

/// The look settings: skin, light or dark, whether each item shows the app it came from, and
/// whether the app's icon in Finder follows the skin. Nothing is written until the user changes one.
struct ShelfPreferences: Equatable, Sendable {
    static let skinKey = "ClipboardShelfSkinV1"
    static let appearanceKey = "ClipboardShelfAppearanceV1"
    static let sourceIconsKey = "ClipboardShelfShowSourceIconsV1"
    static let appIconKey = "ClipboardShelfAppIconFollowsSkinV1"
    /// Written with every save from 1.3.0. Before it, saving any look setting also wrote the skin,
    /// so a stored Lagoon without this marker was the old default rather than a choice.
    static let defaultsVersionKey = "ClipboardShelfLookDefaultsVersion"
    static let defaultsVersion = 2

    var skin = ShelfSkin.fallback
    var appearance = ShelfAppearance.auto
    /// On unless the user turned it off.
    var showSourceIcons = true
    /// On unless the user turned it off.
    var appIconFollowsSkin = true

    static func load(from defaults: UserDefaults = .standard) -> ShelfPreferences {
        var skin = ShelfSkin.from(stored: defaults.string(forKey: skinKey))
        if skin == .lagoon, defaults.object(forKey: defaultsVersionKey) == nil {
            skin = .fallback
        }
        return ShelfPreferences(
            skin: skin,
            appearance: ShelfAppearance.from(stored: defaults.string(forKey: appearanceKey)),
            showSourceIcons: defaults.object(forKey: sourceIconsKey) as? Bool ?? true,
            appIconFollowsSkin: defaults.object(forKey: appIconKey) as? Bool ?? true
        )
    }

    func save(to defaults: UserDefaults = .standard) {
        defaults.set(skin.rawValue, forKey: Self.skinKey)
        defaults.set(appearance.rawValue, forKey: Self.appearanceKey)
        defaults.set(showSourceIcons, forKey: Self.sourceIconsKey)
        defaults.set(appIconFollowsSkin, forKey: Self.appIconKey)
        defaults.set(Self.defaultsVersion, forKey: Self.defaultsVersionKey)
    }

    /// The skin whose icon the app should show in Finder, or nil for the app's own icon.
    var customIconSkin: ShelfSkin? {
        appIconFollowsSkin && skin != ShelfSkin.builtInIcon ? skin : nil
    }
}
